Lemma rt_mmap_grant : forall addr len flags avoid rsp a R R',
  fstepA (NMmap addr len (PROT_READ + PROT_WRITE) flags) rsp R R' ->
  dec_mmap ATOP len avoid rsp = Some (MmOk a) -> (0 <= len)%Z ->     (* [comment removed for export] *)
